def transform(grid):
    n = len(grid)
    m = len(grid[0])

    def rotate_cw(a):
        return [list(row) for row in zip(*a[::-1])]

    def rotate_ccw(a):
        return [list(row) for row in zip(*a)][::-1]

    def rotate_180(a):
        return [row[::-1] for row in a[::-1]]

    tiles = [
        [row[:] for row in grid],
        rotate_cw(grid),
        rotate_ccw(grid),
        rotate_180(grid),
    ]
    out = [[0] * (2 * m) for _ in range(2 * n)]
    for r in range(n):
        for c in range(m):
            out[r][c] = tiles[0][r][c]
            out[r][c + m] = tiles[1][r][c]
            out[r + n][c] = tiles[2][r][c]
            out[r + n][c + m] = tiles[3][r][c]
    return out
